import { streamifyResponse } from 'awslambda';

// 从环境变量加载路由配置
const ROUTES = JSON.parse(process.env.UPSTREAM_ROUTES || '{}');
const providers = ROUTES.providers || [];
const defaultRoute = ROUTES.default || null;

// 根据 Bearer Token 查找供应商
function findProvider(token) {
  return providers.find(p => p.api_key === token) || null;
}

// 校验模型是否被供应商支持
function isModelAllowed(provider, model) {
  const allowed = provider.models;
  if (!allowed || allowed.length === 0) return true; // 无限制
  return allowed.includes(model);
}

export const handler = streamifyResponse(async (event, responseStream, context) => {
  const headers = event.headers || {};
  const requestPath = event.rawPath || '/v1/messages';
  const method = event.requestContext?.http?.method || 'POST';

  // 1. 记录请求基本信息
  console.log('========== INCOMING REQUEST ==========');
  console.log('Method:', method, 'Path:', requestPath);
  console.log('Headers:', JSON.stringify(headers, null, 2));
  console.log('Body:', event.body);
  console.log('======================================');

  // 2. 解析客户端 API Key
  const authHeader = headers['authorization'] || '';
  const token = authHeader.replace(/^Bearer\s+/i, '').trim();

  // 3. 路由决策
  let provider = findProvider(token);
  let upstream, allowedModels;

  if (provider) {
    upstream = provider.upstream;
    allowedModels = provider.models;
    console.log(`Matched provider: ${provider.name}, upstream: ${upstream.base_url}`);
  } else if (defaultRoute && defaultRoute.upstream) {
    upstream = defaultRoute.upstream;
    allowedModels = defaultRoute.models;
    console.log(`No provider matched, using default upstream: ${upstream.base_url}`);
  } else {
    console.error('No matching provider or default route');
    responseStream.setContentType('application/json');
    responseStream.write(JSON.stringify({ error: 'Unauthorized or no route configured' }));
    responseStream.end();
    return;
  }

  // 4. 模型白名单校验
  let model;
  try {
    const body = JSON.parse(event.body);
    model = body.model || '';
  } catch (e) {
    model = '';
  }

  if (allowedModels && allowedModels.length > 0 && !allowedModels.includes(model)) {
    console.error(`Model ${model} not allowed for this provider`);
    responseStream.setContentType('application/json');
    responseStream.write(JSON.stringify({ error: `Model ${model} not supported` }));
    responseStream.end();
    return;
  }

  // 5. 构造上游请求
  const upstreamUrl = `${upstream.base_url.replace(/\/$/, '')}${requestPath}`;
  const forwardHeaders = {};
  if (headers['content-type']) forwardHeaders['content-type'] = headers['content-type'];
  forwardHeaders['authorization'] = authHeader; // 透传原始 key（上游按需验证）

  try {
    // 6. 发起上游流式请求
    const upstreamResp = await fetch(upstreamUrl, {
      method,
      headers: forwardHeaders,
      body: event.body,
    });

    console.log('========== UPSTREAM RESPONSE ==========');
    console.log('Status:', upstreamResp.status);
    const respHeaders = {};
    upstreamResp.headers.forEach((v, k) => { respHeaders[k] = v; });
    console.log('Headers:', JSON.stringify(respHeaders, null, 2));

    // 7. 设置客户端 SSE 响应头
    responseStream.setContentType('text/event-stream');
    responseStream.setHeader('Cache-Control', 'no-cache');
    responseStream.setHeader('Connection', 'keep-alive');

    // 8. 流式透传上游响应体
    const reader = upstreamResp.body.getReader();
    const decoder = new TextDecoder();

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      const chunkText = decoder.decode(value, { stream: true });
      console.log('SSE chunk:', chunkText); // 记录到 CloudWatch
      responseStream.write(value);
    }

    console.log('========== STREAM END ==========');
    responseStream.end();

  } catch (err) {
    console.error('Proxy error:', err);
    if (!responseStream.destroyed) {
      responseStream.write(`event: error\ndata: ${JSON.stringify({ error: err.message })}\n\n`);
      responseStream.end();
    }
  }
});

