function ConvertFrom-YamlSimple {
    param([string]$Yaml)

    $lines = $Yaml -split "`n"
    $root = [System.Collections.Specialized.OrderedDictionary]::new()
    $stack = @(@{ obj = $root; indent = -1 })

    $i = 0
    while ($i -lt $lines.Count) {
        $rawLine = $lines[$i]
        $line = $rawLine.TrimEnd()
        $i++

        if ($line -match '^\s*#' -or $line -match '^\s*$') { continue }

        # 计算缩进
        $trimmed = $line.TrimStart()
        $indent = $line.Length - $trimmed.Length

        # 弹出栈中缩进 >= 当前的项
        while ($stack.Count -gt 1 -and $stack[-1].indent -ge $indent) {
            $stack = $stack[0..($stack.Count - 2)]
        }

        $current = $stack[-1].obj

        # 匹配列表项: "- value"
        if ($trimmed -match '^- (.+)$') {
            $val = ParseYamlValue $Matches[1]

            # 检查当前容器是否是字典中的占位符（需要转为列表）
            if ($current -is [System.Collections.Specialized.OrderedDictionary]) {
                $lastKey = $stack[-1].lastKey
                if ($lastKey -and $current[$lastKey] -is [System.Collections.Specialized.OrderedDictionary] -and $current[$lastKey].Count -eq 0) {
                    $list = [System.Collections.ArrayList]::new()
                    $current[$lastKey] = $list
                    # 如果值是简单类型，加入列表
                    if ($val -isnot [System.Collections.Specialized.OrderedDictionary]) {
                        $list.Add($val) | Out-Null
                    } else {
                        $list.Add($val) | Out-Null
                    }
                    continue
                }
            }

            # 当前就是列表
            if ($current -is [System.Collections.ArrayList]) {
                $current.Add($val) | Out-Null
            }
            continue
        }

        # 匹配键值对: "Key: value" 或 "Key:"
        if ($trimmed -match '^(\w[\w]*):\s*(.*)$') {
            $key = $Matches[1]
            $valStr = $Matches[2].Trim()

            if ($valStr -eq '' -or $valStr -match '^\s*$') {
                # 空值，创建子对象，压栈
                $newObj = [System.Collections.Specialized.OrderedDictionary]::new()
                $current[$key] = $newObj
                $stack[-1].lastKey = $key
                $stack += @{ obj = $newObj; indent = $indent }
            } else {
                $current[$key] = ParseYamlValue $valStr
                $stack[-1].lastKey = $key
            }
            continue
        }
    }

    return $root
}

