"""
server_local.py - 本地 Lambda 运行时模拟服务器
在本地启动 HTTP 服务器，加载 index.mjs 中的 Lambda handler，
模拟 awslambda 运行时环境，用于 test_http.py 发送真实 HTTP 请求测试。

用法:
  python3 server_local.py              # 启动服务器（默认端口 9000）
  python3 server_local.py --port 9000  # 指定端口

然后另开终端运行:
  python3 test_http.py --url http://localhost:9000
"""

import argparse
import json
import os
import subprocess
import sys
import tempfile
import threading
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse


# ── 生成 Node.js 测试服务端代码 ──
SERVER_JS = r"""
// server_local_runner.mjs - 由 server_local.py 自动生成
// 模拟 Lambda 运行时环境，加载 index.mjs 的 handler 并启动 HTTP 服务

import { createServer } from 'http';

// ── 模拟 awslambda 全局对象 ──
globalThis.awslambda = {
  streamifyResponse(handlerFn) {
    return async (event, context) => {
      let outputChunks = [];
      let currentMeta = { statusCode: 200, headers: {} };

      const stream = {
        write(data) { outputChunks.push(Buffer.isBuffer(data) ? data.toString() : data); },
        end(data) { if (data) this.write(data); },
        get destroyed() { return false; },
      };

      const wrapped = awslambda.HttpResponseStream.from(stream, currentMeta);

      try {
        await handlerFn(event, wrapped, context);
      } catch (e) {
        // 如果 handler 内部未捕获，这里兜底
        if (!wrapped._ended) {
          wrapped.end(JSON.stringify({ error: e.message }));
        }
      }

      return {
        output: outputChunks.join(''),
        meta: wrapped.__meta || currentMeta,
      };
    };
  },
  HttpResponseStream: {
    from(stream, meta) {
      const m = { statusCode: meta.statusCode || 200, headers: meta.headers || {} };
      return Object.assign(Object.create(stream), {
        __meta: m,
        _ended: false,
        write(data) { stream.write(data); },
        end(data) {
          if (data) stream.write(data);
          this._ended = true;
        },
      });
    }
  }
};

// ── 加载被测 handler ──
const handler = (await import('./index.mjs')).handler;

// ── 启动 HTTP 服务器 ──
const PORT = parseInt(process.env.PORT || '9000', 10);

const server = createServer(async (req, res) => {
  // 只处理 POST 请求
  if (req.method !== 'POST') {
    res.writeHead(405, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: '仅支持 POST 请求' }));
    return;
  }

  // 收集请求体
  let body = '';
  req.on('data', chunk => { body += chunk; });
  req.on('end', async () => {
    // 构造 Lambda 事件对象
    const event = {
      headers: req.headers,
      rawPath: req.url || '/v1/messages',
      requestContext: {
        http: { method: req.method },
      },
      body: body || '{}',
    };

    try {
      const result = await handler(event, {});

      const { statusCode, headers: respHeaders } = result.meta;
      const output = result.output;

      // 设置响应头
      const responseHeaders = {
        'Content-Type': respHeaders['content-type'] || 'application/json',
        'Access-Control-Allow-Origin': '*',
      };
      if (respHeaders['cache-control']) responseHeaders['Cache-Control'] = respHeaders['cache-control'];
      if (respHeaders['connection']) responseHeaders['Connection'] = respHeaders['connection'];

      res.writeHead(statusCode || 200, responseHeaders);
      res.end(output || '');

    } catch (err) {
      res.writeHead(500, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: err.message }));
    }
  });
});

server.listen(PORT, () => {
  console.log(`[server_local] Lambda 模拟服务器已启动: http://localhost:${PORT}`);
  console.log(`[server_local] 按 Ctrl+C 停止`);
});

// 优雅退出
process.on('SIGINT', () => {
  console.log('\n[server_local] 正在关闭...');
  server.close(() => process.exit(0));
});
"""


def start_server(port=9000):
    """启动本地 Lambda 模拟服务器"""
    project_dir = os.path.dirname(os.path.abspath(__file__))

    # 检查 index.mjs 是否存在
    index_path = os.path.join(project_dir, "index.mjs")
    if not os.path.exists(index_path):
        print(f"错误: 未找到 {index_path}")
        print("请确保在项目目录中运行此脚本")
        sys.exit(1)

    # 写入临时 runner 文件
    runner_path = os.path.join(project_dir, "server_local_runner.mjs")
    with open(runner_path, "w", encoding="utf-8") as f:
        f.write(SERVER_JS)

    env = os.environ.copy()
    env["PORT"] = str(port)

    print(f"正在启动 Lambda 模拟服务器 (端口: {port})...")
    print(f"项目目录: {project_dir}")
    print()

    try:
        proc = subprocess.Popen(
            ["node", runner_path],
            cwd=project_dir,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
        )

        # 等待服务器启动
        import time
        time.sleep(1)

        # 检查进程是否还在运行
        if proc.poll() is not None:
            print("服务器启动失败:")
            stdout, _ = proc.communicate()
            print(stdout)
            sys.exit(1)

        # 输出服务器日志（后台线程）
        def log_output():
            for line in proc.stdout:
                print(line, end="", flush=True)

        log_thread = threading.Thread(target=log_output, daemon=True)
        log_thread.start()

        print(f"服务器已启动: http://localhost:{port}")
        print(f"在另一个终端中运行测试: python3 test_http.py --url http://localhost:{port}")
        print("按 Ctrl+C 停止服务器")
        print()

        # 等待进程结束
        proc.wait()

    except KeyboardInterrupt:
        print("\n正在停止服务器...")
        proc.terminate()
        proc.wait()
    finally:
        # 清理临时文件
        if os.path.exists(runner_path):
            os.remove(runner_path)


def main():
    parser = argparse.ArgumentParser(description="本地 Lambda 运行时模拟服务器")
    parser.add_argument("--port", type=int, default=9000, help="监听端口（默认: 9000）")
    args = parser.parse_args()

    start_server(port=args.port)


if __name__ == "__main__":
    main()

