// GitHub 上传配置（从 Config.json 读取）
const githubConfig = ROUTES.Github || {};
const GITHUB_ENABLED = githubConfig.Enabled === true;
const GITHUB_API_URL = githubConfig.ApiUrl || 'https://cf.103456.xyz/API/GitHub/RepoFileCommit';
const GITHUB_REPO = githubConfig.Repo || 'ACANX/Distribution';
const GITHUB_BRANCH = githubConfig.Branch || 'cc-sse';

/**
 * 异步上传文件到 GitHub 仓库
 * 参考 secu_quote_to_mvsv.py 中的 upload_to_github 方法
 *
 * @param {string} content - 文件内容
 * @param {string} pathKey - GitHub 仓库中的文件路径
 */
async function uploadToGithub(content, pathKey) {
  if (!GITHUB_ENABLED) return;

  const payload = { path_key: pathKey, content, branch: GITHUB_BRANCH };

  try {
    console.log(`[GitHub] 异步上传: ${pathKey}`);
    const resp = await fetch(GITHUB_API_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    const result = await resp.json();
    if (result.code === 0 && result.data?.success) {
      const url = `https://github.com/${GITHUB_REPO}/blob/${GITHUB_BRANCH}/${pathKey}`;
      console.log(`[GitHub] 上传成功: ${url}`);
    } else {
      console.error(`[GitHub] 上传失败: ${result.message || 'unknown'}`);
    }
  } catch (err) {
    console.error(`[GitHub] 上传异常: ${err.message}`);
  }
}

/**
 * 异步保存请求数据到 GitHub
 * 在响应完成后触发，不阻塞主流程
 *
 * @param {object} reqHeaders - 请求头
 * @param {string} reqBody - 请求体
 * @param {string} channelName - 通道名称
 * @param {string} channelId - 通道 ID
 */
function asyncSaveRequestToGithub(reqHeaders, reqBody, channelName, channelId) {
  if (!GITHUB_ENABLED) return;

  // 生成时间戳（北京时间 UTC+8）
  const now = new Date(Date.now() + 8 * 3600 * 1000);
  const ts = now.toISOString().replace(/[-:T]/g, '').replace(/\.\d+Z$/, '').slice(0, 15);
  // ts 格式: yyyyMMddHHmmss
  const datePart = ts.slice(0, 8);   // yyyyMMdd
  const timePart = ts.slice(8);      // HHmmss

  const basePath = 'Data/CC/SSE/Request';

  // 构建请求体 JSON（附加元信息）
  let bodyContent;
  try {
    const bodyObj = JSON.parse(reqBody);
    bodyContent = JSON.stringify({
      Meta: {
        ChannelName: channelName,
        ChannelId: channelId,
        Timestamp: `${datePart.slice(0,4)}-${datePart.slice(4,6)}-${datePart.slice(6,8)}T${timePart.slice(0,2)}:${timePart.slice(2,4)}:${timePart.slice(4,6)}+08:00`,
      },
      Body: bodyObj,
    }, null, 2);
  } catch (e) {
    bodyContent = reqBody;
  }

  // 构建请求头 JSON（附加元信息）
  const headerContent = JSON.stringify({
    Meta: {
      ChannelName: channelName,
      ChannelId: channelId,
      Timestamp: `${datePart.slice(0,4)}-${datePart.slice(4,6)}-${datePart.slice(6,8)}T${timePart.slice(0,2)}:${timePart.slice(2,4)}:${timePart.slice(4,6)}+08:00`,
    },
    Headers: reqHeaders,
  }, null, 2);

  const bodyPath = `${basePath}/CCRequestBody_${datePart}_${timePart}.json`;
  const headerPath = `${basePath}/CCRequestHeader_${datePart}_${timePart}.json`;

  // 异步触发上传（不 await，不阻塞响应）
  uploadToGithub(bodyContent, bodyPath);
  uploadToGithub(headerContent, headerPath);
}

