    }
    console.log(displayChunk);

    // SSE 模式：只保存第一条事件的响应数据
    // 第一条事件格式：event: message_start\ndata: {...}\n\n
    if (!firstSSEChunk && chunkText.includes('event: message_start')) {
      firstSSEChunk = chunkText;
    } else if (!firstSSEChunk && chunkText.includes('data: ') && chunkText.includes('type":"message_start')) {
      firstSSEChunk = chunkText;
    }
  }

  responseStream.write(value);
}

// 非 SSE 模式：记录完整响应体日志
if (!isSSE) {
  console.log('响应体:');
  let displayBody = fullBody;
  if (fullBody.startsWith('{') || fullBody.startsWith('[')) {
