# test-local.mjs - 本地模拟 Lambda 流式响应测试
# 用法: node test-local.mjs

// ── 模拟 awslambda 全局对象（Lambda 运行时注入） ──
const { Writable } = await import('stream');

globalThis.awslambda = {
  streamifyResponse(handlerFn) {
    return async (event, context) => {
      // 模拟 responseStream（记录写入的数据用于验证）
      let outputChunks = [];
      let metadata = { statusCode: 200, headers: {} };

      const mockStream = new Writable({
        write(chunk, encoding, callback) {
          outputChunks.push(chunk.toString());
          callback();
        },
        final(callback) {
          callback();
        }
      });

      // HttpResponseStream.from 模拟
      mockStream.__setMetadata = (statusCode, headers) => {
        metadata = { statusCode, headers };
      };

      const responseStream = mockStream;

      await handlerFn(event, responseStream, context);

      return { output: outputChunks.join(''), metadata };
    };
  },
  HttpResponseStream: {
    from(stream, meta) {
      const { statusCode, headers } = meta;
      // 记录元数据
      stream.__metadata = meta;
      stream.__statusCode = statusCode;
      stream.__headers = headers;
      // 返回一个包装对象，保留 write/end
      const wrapped = {
        _stream: stream,
        _metadata: meta,
        write(data) { stream.write(data); },
        end(data) {
          if (data) stream.write(data);
          stream.end();
        },
        get destroyed() { return stream.destroyed; },
      };
      // 让控制台能看到 metadata
      wrapped.__metadata = meta;
      return wrapped;
    }
  }
};

// ── 加载被测代码 ──
const handler = (await import('./index.mjs')).handler;

// ── 辅助函数：捕获 console 输出 ──
function captureLog(fn) {
  const logs = [];
  const origLog = console.log;
  const origError = console.error;
  console.log = (...args) => logs.push({ level: 'log', text: args.map(a => typeof a === 'object' ? JSON.stringify(a, null, 2) : String(a)).join(' ') });
  console.error = (...args) => logs.push({ level: 'error', text: args.map(a => typeof a === 'object' ? JSON.stringify(a, null, 2) : String(a)).join(' ') });
  try {
    fn();
  } finally {
    console.log = origLog;
    console.error = origError;
  }
  return logs;
}

// ── 检查 Config.json 是否正确加载 ──
const { readFileSync } = await import('fs');
const config = JSON.parse(readFileSync('./Config.json', 'utf-8'));
console.log('\n=== Config.json 验证 ===');
console.log('供应商数量:', config.Providers?.length);
console.log('默认路由:', config.Default?.ChannelName);
console.log('模型白名单 (Default):', config.Default?.Models?.join(', '));

// ── 测试案例 ──
const tests = [];

// Test 1: 正常请求 - 匹配供应商
tests.push({
  name: '正常请求 - 匹配 svips 供应商',
  event: {
    headers: {
      'authorization': 'Bearer sk-bc13f6914aafdb5fced563f72561df34',
      'content-type': 'application/json',
    },
    rawPath: '/v1/messages',
    requestContext: { http: { method: 'POST' } },
    body: JSON.stringify({
      model: 'deepseek-v4-flash',
      messages: [{ role: 'user', content: 'Hello' }],
      stream: true
    })
  },
  expectRoute: 'svips',
  expectModelCheck: 'pass',
});

// Test 2: 请求未匹配供应商但命中默认路由
tests.push({
  name: '默认路由 - 未知 API Key 命中默认配置',
  event: {
    headers: {
      'authorization': 'Bearer sk-unknown-key-xxx',
      'content-type': 'application/json',
    },
    rawPath: '/v1/messages',
    requestContext: { http: { method: 'POST' } },
    body: JSON.stringify({
      model: 'GLM-5.1',
      messages: [{ role: 'user', content: 'Hi' }],
      stream: true
    })
  },
  expectRoute: 'default',
  expectModelCheck: 'pass',
});

// Test 3: 模型不在白名单 - 应被拒绝
tests.push({
  name: '模型拒绝 - svips 不允许使用 gpt-4',
  event: {
    headers: {
      'authorization': 'Bearer sk-bc13f6914aafdb5fced563f72561df34',
      'content-type': 'application/json',
    },
    rawPath: '/v1/messages',
    requestContext: { http: { method: 'POST' } },
    body: JSON.stringify({
      model: 'gpt-4',
      messages: [{ role: 'user', content: 'Hi' }],
      stream: true
    })
  },
  expectRoute: 'svips',
  expectModelCheck: 'rejected',
});

// Test 4: 无供应商匹配且无默认路由 - 模拟空配置
tests.push({
  name: '未授权 - 无路由匹配（跳过，需要特殊配置）',
  skip: true,
});

// Test 5: 验证日志格式 - 标题和内容是否分行
tests.push({
  name: '日志格式验证 - 检查标题后换行输出',
  event: {
    headers: {
      'authorization': 'Bearer sk-bc13f6914aafdb5fced563f72561df34',
      'content-type': 'application/json',
    },
    rawPath: '/v1/messages',
    requestContext: { http: { method: 'POST' } },
    body: JSON.stringify({
      model: 'deepseek-v4-flash',
      messages: [{ role: 'user', content: 'Test for log format' }],
      stream: true
    })
  },
  expectRoute: 'svips',
  expectModelCheck: 'pass',
  checkLogFormat: true,
});

console.log('\n========================================');
console.log('开始测试 (' + tests.filter(t => !t.skip).length + ' 项)');
console.log('========================================\n');

let passed = 0;
let failed = 0;

for (const test of tests) {
  if (test.skip) {
    console.log(`⏭️  跳过: ${test.name}`);
    continue;
  }

  console.log(`▶️  测试: ${test.name}`);

  // 先找代码的 init 部分 - 不需要重新加载 index.mjs
  // 直接运行 handler，捕获日志
  const logs = [];

  try {
    // 替换 console 捕获日志
    const origLog = console.log;
    const origError = console.error;
    const capturedLogs = [];
    console.log = (...args) => capturedLogs.push({ level: 'log', text: args.map(a => typeof a === 'object' ? JSON.stringify(a, null, 2) : String(a)).join(' ') });
    console.error = (...args) => capturedLogs.push({ level: 'error', text: args.map(a => typeof a === 'object' ? JSON.stringify(a, null, 2) : String(a)).join(' ') });

    try {
      const result = await handler(test.event, {});
      const logText = capturedLogs.map(l => l.text).join('\n');

      // 验证结果
      let allOk = true;

      // 检查日志包含路由信息
      if (test.expectRoute === 'svips') {
        if (logText.includes('匹配供应商: svips')) {
          console.log('  ✅ 路由匹配: svips');
        } else {
          console.log('  ❌ 路由匹配: 未找到 svips');
          allOk = false;
        }
      } else if (test.expectRoute === 'default') {
        if (logText.includes('使用默认通道')) {
          console.log('  ✅ 路由匹配: 默认通道');
        } else {
          console.log('  ❌ 路由匹配: 未找到默认通道');
          allOk = false;
        }
      }

      // 检查模型校验
      if (test.expectModelCheck === 'rejected') {
        if (logText.includes('不允许') || logText.includes('不被支持')) {
          console.log('  ✅ 模型拒绝: 正确拦截');
          // 检查返回的 error
          if (result && result.output) {
            try {
              const errData = JSON.parse(result.output);
              if (errData.error) {
                console.log('  ✅ 错误信息中文: ' + errData.error);
              }
            } catch (e) {}
          }
        } else {
          console.log('  ❌ 模型拒绝: 未拦截');
          allOk = false;
        }
      } else if (test.expectModelCheck === 'pass') {
        if (logText.includes('上游响应') || logText.includes('fetch')) {
          console.log('  ✅ 模型校验通过（将进入 fetch 阶段）');
        } else if (!logText.includes('不允许') && !logText.includes('不被支持')) {
          console.log('  ✅ 模型校验: 未拒绝（符合预期）');
        }
      }

      // 检查日志格式（标题和内容是否分行）
      if (test.checkLogFormat) {
        // 检查 "请求头:" 之后应该跟一个格式化 JSON（以 { 开头在下一行）
        let formatOk = true;
        for (let i = 0; i < capturedLogs.length - 1; i++) {
          const current = capturedLogs[i].text.trim();
          const next = capturedLogs[i + 1].text.trim();

          if (current === '请求头:' || current === '请求体:' || current === '响应头:') {
            // 检查下一行是否以 { 开头（JSON 格式化输出）
            if (next.startsWith('{') || next.startsWith('[')) {
              // OK
            } else {
              // 非 JSON 也允许
            }
            console.log(`  ℹ️  日志格式: "${current}" 下一行是以 ${next.startsWith('{') ? '{' : next.startsWith('[') ? '[' : '非JSON'} 开头`);
          }
        }
      }

      if (allOk) {
        console.log('  🟢 通过');
        passed++;
      } else {
        failed++;
      }

      // 打印关键日志摘要
      const keyLines = capturedLogs
        .filter(l => !l.text.includes('=========='))
        .map(l => `    ${l.level === 'error' ? 'ERROR' : 'LOG'}: ${l.text.substring(0, 120)}`);
      if (keyLines.length > 0) {
        console.log('  📋 日志摘要:');
        keyLines.forEach(l => console.log(l));
      }

    } catch (handlerErr) {
      // fetch 错误是预期的（本地没有上游服务器），检查到 fetch 之前的部分是否正确
      const logText = capturedLogs.map(l => l.text).join('\n');
      if (logText.includes('fetch') && (handlerErr.message.includes('fetch') || handlerErr.message.includes('ECONNREFUSED') || handlerErr.cause?.code === 'ECONNREFUSED')) {
