// ── 4. 辅助：捕获日志 ──
function captureLogs(fn) {
  const logs = [];
  const origLog = console.log;
  const origError = console.error;
  console.log = (...args) => {
    const text = args.map(a => typeof a === 'object' && a !== null ? JSON.stringify(a, null, 2) : String(a)).join(' ');
    logs.push({ level: 'LOG', text });
  };
  console.error = (...args) => {
    const text = args.map(a => typeof a === 'object' && a !== null ? JSON.stringify(a, null, 2) : String(a)).join(' ');
    logs.push({ level: 'ERR', text });
  };
  try {
    fn();
  } finally {
    console.log = origLog;
    console.error = origError;
  }
  return logs;
}

// ── 5. 测试执行 ──
let passed = 0, failed = 0;
function test(name, fn) {
  console.log(`\n▶️  ${name}`);
