    console.log('  ✅ 通过');
    passed++;
  } catch (e) {
    console.log('  ❌ 失败: ' + e.message);
    failed++;
  }
}

function check(cond, msg) {
  if (!cond) throw new Error(msg || '检查失败');
}

function makeEvent(auth, model) {
  return {
    headers: {
      'authorization': auth,
      'content-type': 'application/json',
