10	const __dirname = dirname(__filename);
11	const configPath = join(__dirname, 'Config.json');
12	
13	let ROUTES;
14	try {
15	  const raw = readFileSync(configPath, 'utf-8');
16	  ROUTES = JSON.parse(raw);
17	} catch (e) {
18	  console.error('无法读取配置文件 Config.json:', e.message);
19	  ROUTES = {};
20	}
21	
22	const providers = ROUTES.Providers || [];
23	const defaultRoute = ROUTES.Default || null;
24	
25	// 根据 Bearer Token 查找供应商
26	function findProvider(token) {
27	  return providers.find(p => p.ApiKey === token) || null;
28	}
29	
30	// 校验模型是否被供应商支持
31	function isModelAllowed(provider, model) {
32	  const allowed = provider.Models;
33	  if (!allowed || allowed.length === 0) return true; // 无限制
34	  return allowed.includes(model);
35	}
