39	// 必须通过 awslambda.HttpResponseStream.from() 注入 metadata（nodejs18 同样兼容此写法）。
40	function withMetadata(responseStream, statusCode, headers) {
41	  return awslambda.HttpResponseStream.from(responseStream, { statusCode, headers });
42	}
