// 根据 Bearer Token 查找供应商
function findProvider(token) {
  return providers.find(p => p.ApiKey === token) || null;
}

// 校验模型是否被供应商支持
function isModelAllowed(provider, model) {
  const allowed = provider.Models;
  if (!allowed || allowed.length === 0) return true; // 无限制
  return allowed.includes(model);
}

// 用 HttpResponseStream 包装响应流，设置 HTTP 状态码与响应头。
// 注意：nodejs20+ 运行时 responseStream 是原始 Writable 流，没有 setContentType/setHeader 方法，
// 必须通过 awslambda.HttpResponseStream.from() 注入 metadata（nodejs18 同样兼容此写法）。
function withMetadata(responseStream, statusCode, headers) {
  return awslambda.HttpResponseStream.from(responseStream, { statusCode, headers });
}

// ── GitHub 异步上传（可选，通过配置开关控制） ──

const githubConfig = ROUTES.Github || {};
const GITHUB_ENABLED = githubConfig.Enabled === true;
const GITHUB_API_URL = githubConfig.ApiUrl || 'https://cf.103456.xyz/API/GitHub/RepoFileCommit';
const GITHUB_REPO = githubConfig.Repo || 'ACANX/Distribution';
const GITHUB_BRANCH = githubConfig.Branch || 'cc-sse';

async function uploadToGithub(content, pathKey) {
  if (!GITHUB_ENABLED) return;
  const payload = { path_key: pathKey, content, branch: GITHUB_BRANCH };
  try {
    console.log(`[GitHub] 异步上传: ${pathKey}`);
    const resp = await fetch(GITHUB_API_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    const result = await resp.json();
    if (result.code === 0 && result.data?.success) {
      console.log(`[GitHub] 上传成功: https://github.com/${GITHUB_REPO}/blob/${GITHUB_BRANCH}/${pathKey}`);
    } else {
      console.error(`[GitHub] 上传失败: ${result.message || 'unknown'}`);
    }
  } catch (err) {
    console.error(`[GitHub] 上传异常: ${err.message}`);
  }
}

function asyncSaveRequestToGithub(reqHeaders, reqBody, channelName, channelId) {
  if (!GITHUB_ENABLED) return;
  const now = new Date(Date.now() + 8 * 3600 * 1000);
  const ts = now.toISOString().replace(/[-:T]/g, '').replace(/\.\d+Z$/, '').slice(0, 15);
  const datePart = ts.slice(0, 8);
  const timePart = ts.slice(8);
  const basePath = 'Data/CC/SSE/Request';

  let bodyContent;
  try {
    const bodyObj = JSON.parse(reqBody);
    bodyContent = JSON.stringify({
      Meta: { ChannelName: channelName, ChannelId: channelId, Timestamp: `${datePart.slice(0,4)}-${datePart.slice(4,6)}-${datePart.slice(6,8)}T${timePart.slice(0,2)}:${timePart.slice(2,4)}:${timePart.slice(4,6)}+08:00` },
      Body: bodyObj,
    }, null, 2);
  } catch (e) { bodyContent = reqBody; }

  const headerContent = JSON.stringify({
    Meta: { ChannelName: channelName, ChannelId: channelId, Timestamp: `${datePart.slice(0,4)}-${datePart.slice(4,6)}-${datePart.slice(6,8)}T${timePart.slice(0,2)}:${timePart.slice(2,4)}:${timePart.slice(4,6)}+08:00` },
    Headers: reqHeaders,
  }, null, 2);

  uploadToGithub(bodyContent, `${basePath}/CCRequestBody_${datePart}_${timePart}.json`);
  uploadToGithub(headerContent, `${basePath}/CCRequestHeader_${datePart}_${timePart}.json`);
}

export const handler = awslambda.streamifyResponse(async (event, responseStream, context) => {
  const headers = event.headers || {};
  const requestPath = event.rawPath || '/v1/messages';
  const method = event.requestContext?.http?.method || 'POST';

  // 1. 记录请求基本信息
  console.log('========== 收到请求 ==========');
  console.log('方法:', method, '路径:', requestPath);
  console.log('请求头:');
  console.log(JSON.stringify(headers, null, 2));
  let formattedBody = event.body;
  if (typeof event.body === 'string') {
    try { formattedBody = JSON.stringify(JSON.parse(event.body), null, 2); } catch (e) { /* 非 JSON 保持原样 */ }
  }
  console.log('请求体:');
  console.log(formattedBody);
  console.log('==============================');

  // 2. 解析客户端 API Key
  const authHeader = headers['authorization'] || '';
  const token = authHeader.replace(/^Bearer\s+/i, '').trim();

  // 3. 路由决策
  let provider = findProvider(token);
  let upstream, allowedModels, channelName, channelId, protocol;

  if (provider) {
    upstream = provider.Upstream;
    allowedModels = provider.Models;
    channelName = provider.ChannelName;
    channelId = provider.ChannelId;
    protocol = provider.Protocol || 'unknown';
    console.log(`匹配供应商: ${provider.Name}, 通道: ${channelName}(${channelId}), 协议: ${protocol}, 上游: ${upstream.BaseUrl}`);
  } else if (defaultRoute && defaultRoute.Upstream) {
    upstream = defaultRoute.Upstream;
    allowedModels = defaultRoute.Models;
    channelName = defaultRoute.ChannelName;
    channelId = defaultRoute.ChannelId;
    protocol = defaultRoute.Protocol || 'unknown';
    console.log(`未匹配供应商，使用默认通道: ${channelName}(${channelId}), 协议: ${protocol}, 上游: ${upstream.BaseUrl}`);
  } else {
    console.error('未匹配到供应商且无默认路由');
    responseStream = withMetadata(responseStream, 401, { 'Content-Type': 'application/json' });
    responseStream.write(JSON.stringify({ error: '未授权或未配置路由' }));
    responseStream.end();
    return;
  }

  // 4. 模型白名单校验
  let model;
  try {
    const body = JSON.parse(event.body);
    model = body.model || '';
  } catch (e) { model = ''; }

  if (allowedModels && allowedModels.length > 0 && !allowedModels.includes(model)) {
    console.error(`模型 ${model} 不允许在通道 ${channelName}(${channelId}) 中使用`);
    responseStream = withMetadata(responseStream, 403, { 'Content-Type': 'application/json' });
    responseStream.write(JSON.stringify({ error: `模型 ${model} 不被支持` }));
    responseStream.end();
    return;
  }

  // 5. 构造上游请求
  const upstreamUrl = `${upstream.BaseUrl.replace(/\/$/, '')}${requestPath}`;
  const forwardHeaders = {};
  if (headers['content-type']) forwardHeaders['content-type'] = headers['content-type'];
  forwardHeaders['authorization'] = authHeader;

  console.log('========== 上游请求 ==========');
  console.log('请求 URL:');
  console.log(upstreamUrl);
  console.log('请求头:');
  console.log(JSON.stringify(forwardHeaders, null, 2));
  console.log('请求体:');
  let forwardBodyDisplay = event.body;
  if (typeof event.body === 'string') {
    try { forwardBodyDisplay = JSON.stringify(JSON.parse(event.body), null, 2); } catch (e) { /* 保持原样 */ }
  }
  console.log(forwardBodyDisplay);
  console.log('==============================');

  try {
    // 6. 发起上游流式请求
    const upstreamResp = await fetch(upstreamUrl, {
      method, headers: forwardHeaders, body: event.body,
    });

    console.log('========== 上游响应 ==========');
    console.log('状态码:', upstreamResp.status);
    const respHeaders = {};
    upstreamResp.headers.forEach((v, k) => { respHeaders[k] = v; });
    console.log('响应头:');
    console.log(JSON.stringify(respHeaders, null, 2));

    // 7. 根据上游响应类型自动选择响应模式
    const upstreamContentType = (respHeaders['content-type'] || '').toLowerCase();
    const isSSE = upstreamContentType.includes('text/event-stream');
    console.log(`响应模式: ${isSSE ? 'SSE 流式' : '普通 HTTP'} (Content-Type: ${upstreamContentType})`);

    if (isSSE) {
      responseStream = withMetadata(responseStream, upstreamResp.status, {
        'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache', 'Connection': 'keep-alive',
      });
    } else {
      responseStream = withMetadata(responseStream, upstreamResp.status, {
        'Content-Type': upstreamContentType,
      });
    }

    // 8. 流式透传上游响应体
    const reader = upstreamResp.body.getReader();
    const decoder = new TextDecoder();
    let fullBody = '';

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      const chunkText = decoder.decode(value, { stream: true });
      fullBody += chunkText;
      if (isSSE) {
        console.log('SSE 数据块:');
        let displayChunk = chunkText;
        if (typeof chunkText === 'string' && (chunkText.startsWith('{') || chunkText.startsWith('['))) {
          try { displayChunk = JSON.stringify(JSON.parse(chunkText), null, 2); } catch (e) { /* 保持原样 */ }
        }
        console.log(displayChunk);
      }
      responseStream.write(value);
    }

    if (!isSSE) {
      console.log('响应体:');
      let displayBody = fullBody;
      if (fullBody.startsWith('{') || fullBody.startsWith('[')) {
        try { displayBody = JSON.stringify(JSON.parse(fullBody), null, 2); } catch (e) { /* 保持原样 */ }
      }
      console.log(displayBody);
    }

    console.log('========== 流式传输结束 ==========');

    // 9. 响应完成后异步保存请求数据到 GitHub（可选，通过配置开关控制）
    asyncSaveRequestToGithub(headers, event.body, channelName, channelId);

    responseStream.end();

  } catch (err) {
    console.error('代理错误:', err);
    if (!responseStream.destroyed) {
      responseStream.write(`event: error\ndata: ${JSON.stringify({ error: `代理请求失败: ${err.message}` })}\n\n`);
      responseStream.end();
    }
  }
});

