  const headerContent = JSON.stringify(headers, null, 2);

  // 构建响应体 JSON
  let respBodyContent;
  try {
    respBodyContent = JSON.stringify(JSON.parse(respBody), null, 2);
  } catch (e) {
    respBodyContent = respBody;
  }

  // 构建响应头 JSON
  const respHeaderContent = JSON.stringify(respHeaders, null, 2);

  const bodyPath = `${basePath}/CCRequestBody_${datePart}_${timePart}.json`;
  const headerPath = `${basePath}/CCRequestHeader_${datePart}_${timePart}.json`;
  const respBodyPath = `${basePath}/CCResponseBody_${datePart}_${timePart}.json`;
  const respHeaderPath = `${basePath}/CCResponseHeader_${datePart}_${timePart}.json`;

