  await Promise.all([
    uploadToGithub(bodyContent, bodyPath).catch(err => {
      console.error(`[GitHub] 请求体上传失败: ${err.message}`);
    }),
    uploadToGithub(headerContent, headerPath).catch(err => {
      console.error(`[GitHub] 请求头上传失败: ${err.message}`);
    }),
    uploadToGithub(respBodyContent, respBodyPath).catch(err => {
      console.error(`[GitHub] 响应体上传失败: ${err.message}`);
    }),
    uploadToGithub(respHeaderContent, respHeaderPath).catch(err => {
      console.error(`[GitHub] 响应头上传失败: ${err.message}`);
    }),
  ]);
  console.log('[GitHub] 异步上传任务全部完成');
}

