while (true) {
  const { done, value } = await reader.read();
  if (done) break;

  const chunkText = decoder.decode(value, { stream: true });
  fullBody += chunkText;

  if (isSSE) {
    // SSE 模式：逐块记录日志
    console.log('SSE 数据块:');
    let displayChunk = chunkText;
    if (typeof chunkText === 'string' && (chunkText.startsWith('{') || chunkText.startsWith('['))) {
      try { displayChunk = JSON.stringify(JSON.parse(chunkText), null, 2); } catch (e) { /* 保持原样 */ }
    }
    console.log(displayChunk);

    // SSE 模式：只保存第一条事件的响应数据
    // 第一条事件格式：event: message_start\ndata: {...}\n\n
    if (!firstSSEChunk && chunkText.includes('event: message_start')) {
      firstSSEChunk = chunkText;
    } else if (!firstSSEChunk && chunkText.includes('data: ') && chunkText.includes('type":"message_start')) {
      firstSSEChunk = chunkText;
    }
  }

  responseStream.write(value);
}

// 非 SSE 模式：记录完整响应体日志
if (!isSSE) {
  console.log('响应体:');
  let displayBody = fullBody;
  if (fullBody.startsWith('{') || fullBody.startsWith('[')) {
    try { displayBody = JSON.stringify(JSON.parse(fullBody), null, 2); } catch (e) { /* 保持原样 */ }
  }
  console.log(displayBody);
}

console.log('========== 流式传输结束 ======================================================================================================================================================================================================');

// 9. 先结束响应流，让客户端收到完整响应
responseStream.end();

// 10. 响应结束后异步保存请求/响应数据到 GitHub（可选，通过配置开关控制）
// 注意：必须在 handler 返回前 await，否则 Lambda 会冻结上下文导致上传失败
// 如果是 SSE 模式，只保存第一条事件的响应头 + 响应体
// 如果是 HTTP 模式，保存完整响应头 + 响应体
const savedRespBody = (isSSE && firstSSEChunk) ? firstSSEChunk : fullBody;
await asyncSaveToGithub(headers, event.body, respHeaders, savedRespBody, channelName, channelId);

