// ── 数据脱敏函数 ──

/**
 * 对 API Key 脱敏：保留前缀与后5位，中间用 * 掩盖至少10位
 * 示例: "sk-b50563b5c678956830dbab67be53603de5fe6dad9bef18e5d276dab0cc1b7b70"
 *    → "sk-b50563b5*****************************1b7b70"
 * 安全处理任意长度 Key，不会因长度不足报错。
 */
function maskApiKey(value) {
  if (!value || typeof value !== 'string') return value;
  const s = value.trim();
  if (s.length <= 10) return s; // 太短不掩盖，避免全变成 *
  const suffix = s.slice(-5);
  const prefixEnd = s.startsWith('sk-') ? 6 : 1;
  const prefix = s.slice(0, Math.min(prefixEnd, s.length - 5));
  const maskLen = Math.max(10, s.length - prefix.length - 5);
  return prefix + '*'.repeat(Math.min(maskLen, 100)) + suffix;
}

/**
 * 对域名脱敏：将域名中间部分替换为 *
 * 示例: "hlpbsnovddtx2mgrxztqmuoace0gmwmu.lambda-url.ap-northeast-1.on.aws"
 *    → "hlpbsnovdd*******.lambda-url.ap-northeast-1.on.aws"
 * 保留每个段的首尾部分，中间用 * 替换
 */
function maskHost(value) {
  if (!value || typeof value !== 'string') return value;
  const s = value.trim().toLowerCase();
  // 按 . 分割域名
  const parts = s.split('.');
  const masked = parts.map(part => {
    if (part.length <= 4) return part; // 短段不掩盖
    // 保留首2位和尾2位，中间掩盖
    const keep = Math.max(2, Math.ceil(part.length / 4));
    const front = part.slice(0, keep);
    const back = part.slice(-keep);
    const midLen = part.length - keep * 2;
    if (midLen <= 0) return part;
    return front + '*'.repeat(Math.min(midLen, 50)) + back;
  });
  return masked.join('.');
}

